public static void jankItems(ServerLevel level, BlockPos target, int effectLevel, float efficiency, Entity entity) {
        List<ItemEntity> items = level.getEntities(EntityType.ITEM, new AABB(target).inflate(effectLevel * 0.5), Entity::isAlive);

        if (!items.isEmpty() && level.random.nextFloat() < efficiency && level.getGameRules().getBoolean(GameRules.RULE_DOMOBSPAWNING)) {
            Endermite endermite = EntityType.ENDERMITE.create(level);
            endermite.moveTo(target, 0, entity.getXRot() + 180);
            level.addFreshEntity(endermite);
        }

        items.forEach(item -> {
            level.sendParticles(ParticleTypes.REVERSE_PORTAL, item.getX() + item.getBbWidth() / 2, item.getY() + item.getBbHeight() / 2,
                    item.getZ() + item.getBbWidth() / 2, 1, 0, 0, 0, 0);
            item.moveTo(entity.getPosition(0));
            item.setPickUpDelay(0);
        });

        level.getEntities(EntityType.EXPERIENCE_ORB, new AABB(target).inflate(effectLevel * 0.5), Entity::isAlive).forEach(orb -> orb.moveTo(entity.getPosition(0)));
    }

@SubscribeEvent
    public void onLivingDeath(LivingDeathEvent event) {
        ItemStack itemStack;
        Entity killer;
        if ("trident".equals(event.getSource().getMsgId())
                && event.getSource().getDirectEntity() instanceof ThrownModularItemEntity modularEntity) {
            itemStack = modularEntity.getThrownStack();
            killer = modularEntity.getOwner();
        } else {
            itemStack = Optional.ofNullable(event.getSource().getEntity())
                    .filter(entity -> entity instanceof Player)
                    .map(entity -> (LivingEntity) entity)
                    .map(LivingEntity::getMainHandItem)
                    .filter(stack -> stack.getItem() instanceof IModularItem)
                    .orElse(null);
            killer = event.getSource().getEntity();
        }

        if (itemStack != null) {
            Level level = event.getEntity().level();
            if (!level.isClientSide) {
                int jankLevel = getEffectLevel(itemStack, ItemEffect.janking);
                if (jankLevel > 0) {
                    JankEffect.jankItemsDelayed((ServerLevel) level, event.getEntity().blockPosition(), jankLevel, getEffectEfficiency(itemStack,
                            ItemEffect.janking), killer);
                }

                UnstablePowerMobEffect.onLivingDeath(event.getEntity(), killer);
            }
        }
    }

public void applyBlockBreakEffects(ItemStack itemStack, Level world, BlockState state, BlockPos pos, LivingEntity entity) {
        if (!world.isClientSide) {
            int intuitLevel = getEffectLevel(itemStack, ItemEffect.intuit);
            if (intuitLevel > 0) {
                int xp = state.getExpDrop(world, world.getRandom(), pos, EnchantmentHelper.getItemEnchantmentLevel(Enchantments.BLOCK_FORTUNE, itemStack),
                        EnchantmentHelper.getItemEnchantmentLevel(Enchantments.SILK_TOUCH, itemStack));
                if (xp > 0) {
                    tickHoningProgression(entity, itemStack, xp * intuitLevel);
                }
            }

            int jankLevel = getEffectLevel(itemStack, ItemEffect.janking);
            if (jankLevel > 0) {
                JankEffect.jankItemsDelayed((ServerLevel) world, pos, jankLevel, getEffectEfficiency(itemStack, ItemEffect.janking), entity);
            }

            int skulkTaintLevel = getEffectLevel(itemStack, ItemEffect.sculkTaint);
            if (skulkTaintLevel > 0) {
                SculkTaintEffect.perform((ServerLevel) world, pos, skulkTaintLevel, getEffectEfficiency(itemStack, ItemEffect.sculkTaint));
            }

            DataEffectsHandler.applyBreakBlockEffects(itemStack, entity, pos);
        }
    }

public static void schedule(int delay, Runnable task) {
        queue.add(new Task(counter + delay, task));
    }

@SubscribeEvent
    public static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) {
            return;
        }

        for (Iterator<Task> it = queue.iterator(); it.hasNext(); ) {
            Task task = it.next();
            if (task.getTick() < counter) {
                task.run();
                it.remove();
            }
        }

        counter++;
    }
